from typing import List, Optional


class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def build_list(values):
    dummy = ListNode()
    cur = dummy
    for v in values:
        cur.next = ListNode(v)
        cur = cur.next
    return dummy.next


def list_to_array(head):
    result = []
    while head:
        result.append(head.val)
        head = head.next
    return result


def test_example_1():
    lists = [build_list([1, 4, 5]), build_list([1, 3, 4]), build_list([2, 6])]
    result = Solution().mergeKLists(lists)
    assert list_to_array(result) == [1, 1, 2, 3, 4, 4, 5, 6]


def test_empty_lists():
    result = Solution().mergeKLists([])
    assert list_to_array(result) == []


def test_list_of_empty():
    result = Solution().mergeKLists([None])
    assert list_to_array(result) == []


def test_single_list():
    result = Solution().mergeKLists([build_list([1, 2, 3])])
    assert list_to_array(result) == [1, 2, 3]


def test_negative_values():
    lists = [build_list([-10, -5, 0]), build_list([-8, -3, 5]), build_list([-1, 2])]
    result = Solution().mergeKLists(lists)
    assert list_to_array(result) == [-10, -8, -5, -3, -1, 0, 2, 5]


def test_mixed_empty_and_nonempty():
